\documentclass[border=10pt]{standalone}
\usepackage{pgfplots}
\usepgfplotslibrary{colormaps}
\pgfplotsset{compat=1.18}

\begin{document}
\begin{tikzpicture}
\begin{axis}[
    view={45}{20},
    xlabel={$x$},
    ylabel={$y$},
    zlabel={$z$},
    title={Hyperbolic Paraboloid: $y = z^2 - \frac{x^2}{2}$},
    colormap/viridis,
    colorbar,
    colorbar style={
        at={(1.1,0)},
        anchor=south west,
        height=0.5*\pgfkeysvalueof{/pgfplots/parent axis height},
        title={$y$}
    },
    width=12cm,
    height=10cm,
    samples=30,
    domain=-3:3,
    y domain=-3:3,
    z buffer=sort
]
\addplot3[surf, shader=flat corner] {x^2/2 - z^2};
\end{axis}
\end{tikzpicture}
\end{document}

